"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["10701"],{65735(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.quantidade_calculada_nao_informavel","status":422,"titulo":"A quantidade de uma modalidade calculada pela Lei 12.711 n\xe3o pode ser fixada pelo edital"},"descricao":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.quantidade_calculada_nao_informavel","requisitos":[],"oQueAconteceu":["Numa distribui\xe7\xe3o de vagas com `regraDistribuicaoCodigo` do tipo Lei 12.711,\\numa modalidade cuja composi\xe7\xe3o \xe9 `DENTRO_DO_VR` (sub-reserva) ou\\n`RESIDUAL_DO_VO` (ampla concorr\xeancia) declara uma quantidade em `quadro`\\n(`quantidade`). A quantidade dessas modalidades \xe9 sempre **sa\xedda**\\ndo c\xe1lculo do art. 10 \u2014 nunca entrada; o edital n\xe3o tem como fixar por fora\\num valor que a f\xf3rmula legal determina.","Este \xe9 o par sim\xe9trico de\\n[`quantidade_declarada_obrigatoria`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.quantidade_declarada_obrigatoria):\\na mesma fronteira calculado/declarado, olhada do lado oposto \u2014 l\xe1, a\\nquantidade faltando quando devia estar presente (retirada/suplemento);\\naqui, presente quando devia faltar (sub-reserva/ampla concorr\xeancia). N\xe3o\\nacumula com nenhuma outra viola\xe7\xe3o \u2014 \xe9 a primeira modalidade com a\\nincoer\xeancia, na ordem em que foram selecionadas, que interrompe a cria\xe7\xe3o\\nda configura\xe7\xe3o."],"comoResolver":["Remova a entrada de `quadro` correspondente \xe0s sub-reservas e \xe0 ampla\\nconcorr\xeancia da oferta \u2014 o c\xe1lculo determina a quantidade delas\\nautomaticamente. Informe quantidade s\xf3 para modalidades de retirada\\n(`RETIRA_DE`) ou suplemento (`SUPLEMENTAR_AO_TOTAL`)."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao distribuicao vagas"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);